-- Clean guest addresses (D84; adjustments V3; T79): `/m/<organisation>/<venue>`. The venue's
-- address name becomes unique within its organisation again, and old names of venues and
-- organisations are kept so they keep redirecting. Generated by drizzle-kit, then edited by hand:
-- the de-duplication before the unique rule, and row-level security. One transaction:
--   0. `venues` stops forcing row-level security on its owner for the length of this transaction
--      and stops touching `updated_at` (same reasons as 0015 and 0018);
--   1. two venues of one organisation that share a name today (allowed since 0015, D68): the
--      older keeps it, the others get "-2", "-3", … (the base cut so the whole stays within 63
--      characters), drawn again while taken; then the unique rule;
--   2. the history tables: `venue_slug_history` is tenant-scoped; `organization_slug_history` is
--      a system table like `auth_organization` (its slugs are unique platform-wide);
--   3. back to normal.
-- Privileges come from src/table-access.ts (`pnpm db:roles`).

-- 0. Owner access for the de-duplication; undone at step 3.
ALTER TABLE "restro"."venues" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."venues" DISABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint

-- 1. One name per organisation.
DO $$
DECLARE
  duplicate record;
  base text;
  candidate text;
  attempt int;
BEGIN
  FOR duplicate IN
    SELECT v.id, v.tenant_id, v.slug
    FROM restro.venues v
    WHERE EXISTS (
      SELECT 1 FROM restro.venues older
      WHERE older.tenant_id = v.tenant_id AND older.slug = v.slug
        AND (older.created_at, older.id) < (v.created_at, v.id)
    )
    ORDER BY v.created_at, v.id
  LOOP
    base := left(duplicate.slug, 60);
    base := regexp_replace(base, '-+$', '');
    attempt := 2;
    LOOP
      candidate := base || '-' || attempt::text;
      EXIT WHEN NOT EXISTS (
        SELECT 1 FROM restro.venues taken
        WHERE taken.tenant_id = duplicate.tenant_id AND taken.slug = candidate
      );
      attempt := attempt + 1;
    END LOOP;
    UPDATE restro.venues SET slug = candidate WHERE id = duplicate.id;
  END LOOP;
END
$$;--> statement-breakpoint
ALTER TABLE "restro"."venues" ADD CONSTRAINT "venues_tenant_id_slug_unique" UNIQUE("tenant_id","slug");--> statement-breakpoint

-- 2. The histories.
CREATE TABLE "restro"."organization_slug_history" (
	"slug" text PRIMARY KEY NOT NULL,
	"organization_id" text NOT NULL,
	"replaced_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "organization_slug_history_organization_id" CHECK ("restro"."organization_slug_history"."organization_id" ~ '^tn_[0-9A-Za-z]+$'),
	CONSTRAINT "organization_slug_history_slug_format" CHECK ("restro"."organization_slug_history"."slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length("restro"."organization_slug_history"."slug") <= 63)
);
--> statement-breakpoint
CREATE TABLE "restro"."venue_slug_history" (
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"slug" text NOT NULL,
	"replaced_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "venue_slug_history_pkey" PRIMARY KEY("tenant_id","slug"),
	CONSTRAINT "venue_slug_history_slug_format" CHECK ("restro"."venue_slug_history"."slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length("restro"."venue_slug_history"."slug") <= 63)
);
--> statement-breakpoint
ALTER TABLE "restro"."venue_slug_history" ADD CONSTRAINT "venue_slug_history_tenant_id_tenants_id_fk" FOREIGN KEY ("tenant_id") REFERENCES "restro"."tenants"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restro"."venue_slug_history" ADD CONSTRAINT "venue_slug_history_venue_fk" FOREIGN KEY ("tenant_id","venue_id") REFERENCES "restro"."venues"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "organization_slug_history_organization_id_idx" ON "restro"."organization_slug_history" USING btree ("organization_id");--> statement-breakpoint
CREATE INDEX "venue_slug_history_venue_id_idx" ON "restro"."venue_slug_history" USING btree ("venue_id");--> statement-breakpoint
-- Row-level security: tenant-scoped, for reading and writing alike.
SELECT restro.enable_tenant_rls('restro.venue_slug_history');--> statement-breakpoint

-- 3. Back to normal.
ALTER TABLE "restro"."venues" ENABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."venues" FORCE ROW LEVEL SECURITY;
